import{_ as t,o,c as a,ag as r}from"./chunks/framework.DLWhSH9p.js";const p=JSON.parse('{"title":"Beta testing reference","description":"","frontmatter":{},"headers":[],"relativePath":"guide/beta-testing.md","filePath":"guide/beta-testing.md"}'),d={name:"guide/beta-testing.md"};function s(n,e,c,i,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="beta-testing-reference" tabindex="-1">Beta testing reference <a class="header-anchor" href="#beta-testing-reference" aria-label="Permalink to &quot;Beta testing reference&quot;">​</a></h1><p>A quick-reference page for beta testers: the test data the Marketplace will accept while we&#39;re on Stripe sandbox mode and the platform isn&#39;t yet processing real money.</p><div class="warning custom-block"><p class="custom-block-title">Sandbox only</p><p>Everything on this page is <strong>test data only</strong>. The marketplace is currently wired to Stripe&#39;s sandbox — real card numbers will be rejected, and these test numbers won&#39;t work once we cut over to live mode. Don&#39;t enter your real payment details until we announce the cutover.</p></div><h2 id="stripe-test-cards" tabindex="-1">Stripe test cards <a class="header-anchor" href="#stripe-test-cards" aria-label="Permalink to &quot;Stripe test cards&quot;">​</a></h2><p>Use these in the <strong>Hire</strong> modal (buyer-side checkout) or when adding a card to your saved <strong>Payment methods</strong>. For every test card:</p><ul><li><strong>Expiry</strong> — any future date (e.g. <code>12/34</code>)</li><li><strong>CVC</strong> — any 3 digits (<code>123</code> is fine)</li><li><strong>ZIP / postal code</strong> — any (e.g. <code>12345</code>)</li><li><strong>Name on card</strong> — any name</li></ul><h3 id="successful-payments" tabindex="-1">Successful payments <a class="header-anchor" href="#successful-payments" aria-label="Permalink to &quot;Successful payments&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Number</th><th>What happens</th></tr></thead><tbody><tr><td><code>4242 4242 4242 4242</code></td><td>✓ Standard success — Visa</td></tr><tr><td><code>4000 0566 5566 5556</code></td><td>✓ Standard success — Visa debit</td></tr><tr><td><code>5555 5555 5555 4444</code></td><td>✓ Standard success — Mastercard</td></tr><tr><td><code>3782 822463 10005</code></td><td>✓ Standard success — Amex (4-digit CVC)</td></tr></tbody></table><h3 id="_3d-secure-authentication" tabindex="-1">3D Secure authentication <a class="header-anchor" href="#_3d-secure-authentication" aria-label="Permalink to &quot;3D Secure authentication&quot;">​</a></h3><p>These cards force the &quot;verify with your bank&quot; modal — useful for testing the SCA challenge flow.</p><table tabindex="0"><thead><tr><th>Number</th><th>What happens</th></tr></thead><tbody><tr><td><code>4000 0025 0000 3155</code></td><td>⚠ Requires 3DS authentication; click <strong>Complete</strong> in the test modal</td></tr><tr><td><code>4000 0027 6000 3184</code></td><td>⚠ Requires 3DS authentication; fails if you click <strong>Fail</strong></td></tr></tbody></table><h3 id="declines" tabindex="-1">Declines <a class="header-anchor" href="#declines" aria-label="Permalink to &quot;Declines&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Number</th><th>What happens</th></tr></thead><tbody><tr><td><code>4000 0000 0000 0002</code></td><td>✗ Generic decline (<code>card_declined</code>)</td></tr><tr><td><code>4000 0000 0000 9995</code></td><td>✗ Insufficient funds (<code>insufficient_funds</code>)</td></tr><tr><td><code>4000 0000 0000 9987</code></td><td>✗ Lost card (<code>lost_card</code>)</td></tr><tr><td><code>4000 0000 0000 9979</code></td><td>✗ Stolen card (<code>stolen_card</code>)</td></tr><tr><td><code>4000 0000 0000 0069</code></td><td>✗ Expired card (<code>expired_card</code>)</td></tr><tr><td><code>4000 0000 0000 0127</code></td><td>✗ Incorrect CVC (<code>incorrect_cvc</code>)</td></tr><tr><td><code>4000 0000 0000 0119</code></td><td>✗ Processing error (<code>processing_error</code>)</td></tr></tbody></table><h3 id="disputes-chargebacks" tabindex="-1">Disputes / chargebacks <a class="header-anchor" href="#disputes-chargebacks" aria-label="Permalink to &quot;Disputes / chargebacks&quot;">​</a></h3><p>These cards immediately raise a dispute after a successful charge — handy for testing the buyer-dispute and admin-chargeback flows.</p><table tabindex="0"><thead><tr><th>Number</th><th>What happens</th></tr></thead><tbody><tr><td><code>4000 0000 0000 0259</code></td><td>⚠ Charges succeed, then a chargeback arrives (<code>fraudulent</code>)</td></tr><tr><td><code>4000 0000 0000 1976</code></td><td>⚠ Charges succeed, then a chargeback arrives (<code>product_not_received</code>)</td></tr></tbody></table><p>Stripe&#39;s full reference: <a href="https://docs.stripe.com/testing" target="_blank" rel="noreferrer">https://docs.stripe.com/testing</a>.</p><h2 id="stripe-connect-—-test-bank-accounts-for-sellers" tabindex="-1">Stripe Connect — test bank accounts for sellers <a class="header-anchor" href="#stripe-connect-—-test-bank-accounts-for-sellers" aria-label="Permalink to &quot;Stripe Connect — test bank accounts for sellers&quot;">​</a></h2><p>If you&#39;re testing the <strong>seller onboarding</strong> flow (Settings → Stripe → Set up payouts), Stripe Connect Express will ask for a bank account during the hosted onboarding. Use one of the test routing/account numbers below — Stripe accepts them in sandbox even though the underlying bank doesn&#39;t exist.</p><h3 id="us-sellers-usd-payouts" tabindex="-1">US sellers (USD payouts) <a class="header-anchor" href="#us-sellers-usd-payouts" aria-label="Permalink to &quot;US sellers (USD payouts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Routing number</th><th>Account number</th><th>What happens</th></tr></thead><tbody><tr><td><code>110000000</code></td><td><code>000123456789</code></td><td>✓ Standard success</td></tr><tr><td><code>110000000</code></td><td><code>000111111116</code></td><td>✗ Account closed when first payout is attempted</td></tr><tr><td><code>110000000</code></td><td><code>000111111113</code></td><td>✗ No bank account at this routing number</td></tr></tbody></table><h3 id="other-countries" tabindex="-1">Other countries <a class="header-anchor" href="#other-countries" aria-label="Permalink to &quot;Other countries&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Country</th><th>Test value</th><th>Format</th></tr></thead><tbody><tr><td>UK (GBP)</td><td>Sort code <code>10-88-00</code>, account <code>00012345</code></td><td>✓ Success</td></tr><tr><td>EU (EUR — IBAN)</td><td><code>DE89370400440532013000</code></td><td>✓ Success (Germany)</td></tr><tr><td>Canada (CAD)</td><td>Transit <code>11000</code>, institution <code>000</code>, account <code>000123456789</code></td><td>✓ Success</td></tr><tr><td>Australia (AUD)</td><td>BSB <code>000-000</code>, account <code>000123456</code></td><td>✓ Success</td></tr><tr><td>Japan (JPY)</td><td>Bank <code>1100</code>, branch <code>000</code>, account <code>0001234</code></td><td>✓ Success</td></tr></tbody></table><h3 id="test-identity-kyc-values" tabindex="-1">Test identity / KYC values <a class="header-anchor" href="#test-identity-kyc-values" aria-label="Permalink to &quot;Test identity / KYC values&quot;">​</a></h3><p>Stripe&#39;s hosted Express onboarding also asks for name, date of birth, address, and (in the US) the last 4 of your SSN. In sandbox, use:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Date of birth</td><td><code>01 / 01 / 1901</code> (any DOB in the past works, but this one is the canonical &quot;approves cleanly&quot; value)</td></tr><tr><td>US SSN last 4</td><td><code>0000</code> (auto-approves) or <code>1117</code> (forces &quot;info pending&quot; state)</td></tr><tr><td>Address</td><td>Any valid-looking US address, e.g. <code>address_full_match</code> line <code>address_full_match</code>, city <code>Seattle</code>, ZIP <code>99999</code></td></tr><tr><td>Phone</td><td><code>0000000000</code></td></tr></tbody></table><p>Full Connect testing reference: <a href="https://docs.stripe.com/connect/testing" target="_blank" rel="noreferrer">https://docs.stripe.com/connect/testing</a>.</p><h2 id="dev-personas" tabindex="-1">Dev personas <a class="header-anchor" href="#dev-personas" aria-label="Permalink to &quot;Dev personas&quot;">​</a></h2><p>The deployed test environment ships a fixed cast of seed users. Sign in via the persona-picker (or, on local dev, the <code>X-Dev-User</code> header) and you&#39;ll inherit that persona&#39;s role + state.</p><table tabindex="0"><thead><tr><th>Persona</th><th>Role</th><th>What they&#39;re for</th></tr></thead><tbody><tr><td><strong>Ben Carter</strong> (<code>ben</code>)</td><td>Buyer, onboarded</td><td>The &quot;default buyer&quot; — has contract history with the seed sellers. Use for testing browse, hire, contracts, payments, alerts, public profile.</td></tr><tr><td><strong>Noah Bell</strong> (<code>noah</code>)</td><td>Buyer, onboarded</td><td>A second clean buyer. Use when Ben&#39;s contract history would get in the way (e.g. testing first-time hire UX without his past hires showing up).</td></tr><tr><td><strong>Paul Lambert</strong> (<code>paul</code>)</td><td>Buyer, <strong>un-onboarded</strong></td><td>Fresh buyer with no checklist progress. Use for testing the <code>/me/buyer/start</code> onboarding wizard and the buyer-gate redirect.</td></tr><tr><td><strong>Aria Sato</strong> (<code>aria</code>)</td><td>Seller, enabled</td><td>Voice actor + spokesperson. Has demos, packages, and is browse-discoverable. Use as the &quot;hire someone&quot; target.</td></tr><tr><td><strong>Kai Okafor</strong> (<code>kai</code>)</td><td>Seller, enabled</td><td>Editor. Second enabled seller — gives the browse grid some variety.</td></tr><tr><td><strong>Lina Park</strong> (<code>lina</code>)</td><td>Seller, enabled</td><td>Musician + animator. Third enabled seller — covers the remaining browse categories.</td></tr><tr><td><strong>Olivia Chen</strong> (<code>olivia</code>)</td><td>Seller, <strong>un-onboarded</strong></td><td>Fresh seller with no Stripe account, no demos, no packages, <code>is_enabled=false</code>. Use for testing the seller onboarding wizard at <code>/me/start</code>.</td></tr><tr><td><strong>Zoe Rivera</strong> (<code>zoe</code>)</td><td>Buyer <strong>and</strong> seller</td><td>Multi-role user — exercises the <code>/me/choose</code> persona chooser and the persona-pinning flow.</td></tr><tr><td><strong>Mira Soto</strong> (<code>mira</code>)</td><td>Admin</td><td>Admin console access. Use for testing brand-verification approvals, dispute/chargeback flows, the gig moderation queue, and the refund/webhook ops surfaces.</td></tr></tbody></table><h3 id="how-to-switch-personas" tabindex="-1">How to switch personas <a class="header-anchor" href="#how-to-switch-personas" aria-label="Permalink to &quot;How to switch personas&quot;">​</a></h3><ul><li><strong>Local dev</strong> — set the <code>X-Dev-User</code> header (e.g. via a browser extension) or visit <code>/me/dev?as=&lt;persona&gt;</code> if the dev tooling is enabled.</li><li><strong>Deployed beta</strong> — sign in via the persona-picker on the login page; each persona has its own pre-provisioned identity.</li></ul><h2 id="brand-verification-—-testing-the-txt-record-flow" tabindex="-1">Brand verification — testing the TXT-record flow <a class="header-anchor" href="#brand-verification-—-testing-the-txt-record-flow" aria-label="Permalink to &quot;Brand verification — testing the TXT-record flow&quot;">​</a></h2><p>The buyer brand-verification flow (Settings → Brand) asks you to publish a DNS TXT record at <code>_mossworks-verify.&lt;your-domain&gt;</code> matching a token we issue. To test the <strong>happy path</strong> in sandbox, you have three options:</p><h3 id="option-a-—-use-a-real-domain-you-own-recommended" tabindex="-1">Option A — use a real domain you own (recommended) <a class="header-anchor" href="#option-a-—-use-a-real-domain-you-own-recommended" aria-label="Permalink to &quot;Option A — use a real domain you own (recommended)&quot;">​</a></h3><p>If you control a domain (even a $1/year one), set the TXT record as instructed and click <strong>Verify</strong>. The check runs against real DNS — there&#39;s no test-mode shortcut on the deployed environment.</p><p>A common cheap-domain trick: register a <code>.xyz</code> or <code>.click</code> (≈$1/year on Namecheap or Cloudflare Registrar), point its DNS at Cloudflare, and use Cloudflare&#39;s DNS panel to add the TXT record. Propagation typically takes 1–5 minutes.</p><h3 id="option-b-—-ask-an-admin-to-manually-approve" tabindex="-1">Option B — ask an admin to manually approve <a class="header-anchor" href="#option-b-—-ask-an-admin-to-manually-approve" aria-label="Permalink to &quot;Option B — ask an admin to manually approve&quot;">​</a></h3><p>The admin queue at <code>/admin/brand-verifications</code> includes a <strong>Mark verified</strong> button as a manual override for cases where DNS isn&#39;t viable (small private brands, in-progress domain transfers, etc.). For beta-test approvals, ping Mira (the admin persona) in <code>#mossworks-beta</code> and she&#39;ll flip you through.</p><h3 id="domains-that-won-t-work" tabindex="-1">Domains that won&#39;t work <a class="header-anchor" href="#domains-that-won-t-work" aria-label="Permalink to &quot;Domains that won&#39;t work&quot;">​</a></h3><p>The verifier rejects &quot;private-looking&quot; TLDs to prevent bogus brand claims:</p><ul><li><code>.local</code>, <code>.localhost</code>, <code>.test</code>, <code>.example</code>, <code>.invalid</code></li><li><code>.corp</code>, <code>.home</code>, <code>.lan</code>, <code>.internal</code>, <code>.private</code></li></ul><p>Use a real public TLD (<code>.com</code>, <code>.io</code>, <code>.xyz</code>, etc.) or Option B.</p><h2 id="mock-email-phone-otp" tabindex="-1">Mock email / phone / OTP <a class="header-anchor" href="#mock-email-phone-otp" aria-label="Permalink to &quot;Mock email / phone / OTP&quot;">​</a></h2><p>Email verification is gated on the Keycloak realm — beta testers don&#39;t need to receive a real verification email; the seeded personas come pre-verified.</p><p>The Marketplace does <strong>not</strong> use SMS / phone OTP anywhere in the user flow today. If a screen asks for a phone number (Stripe Connect Express asks for one during seller KYC), any test number that matches the format works — <code>+1 555 555 5555</code> is the convention.</p><h2 id="getting-help" tabindex="-1">Getting help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting help&quot;">​</a></h2><ul><li><strong>Beta channel:</strong> <code>#mossworks-beta</code></li><li><strong>Bugs:</strong> <a href="https://github.com/Mossworks-Labs/marketplace/issues" target="_blank" rel="noreferrer">github.com/Mossworks-Labs/marketplace/issues</a></li><li><strong>Stripe testing reference:</strong> <a href="https://docs.stripe.com/testing" target="_blank" rel="noreferrer">https://docs.stripe.com/testing</a></li><li><strong>Stripe Connect testing reference:</strong> <a href="https://docs.stripe.com/connect/testing" target="_blank" rel="noreferrer">https://docs.stripe.com/connect/testing</a></li></ul>',48)])])}const g=t(d,[["render",s]]);export{p as __pageData,g as default};
